import assert from 'node:assert/strict';
import { readFileSync, writeFileSync } from 'node:fs';
if (!process.env.VOLTER_WORLD) throw new Error('Run this application through its World.');
assert.ok(process.env.BUFFER_BITLY_API_KEY, 'the application receives its account grant');
const headers = { Authorization: `Bearer ${process.env.BUFFER_BITLY_API_KEY}` };
async function get(path) {
  const response = await fetch('https://api-ssl.bitly.com/v4' + path, { headers });
  assert.equal(response.status, 200);
  return response.json();
}
const longUrl = 'https://example.com/observatory/open-evening';
const title = 'Observatory open evening';
const tag = 'community';
let saved;
if (process.argv[2] === 'readback') {
  saved = JSON.parse(readFileSync('bitlink.json', 'utf8'));
} else {
  const user = await get('/user');
  assert.ok(user.login && user.default_group_guid);
  const response = await fetch('https://api-ssl.bitly.com/v4/bitlinks', {
    method: 'POST', headers: { ...headers, 'Content-Type': 'application/json' },
    body: JSON.stringify({ long_url: longUrl, title, tags: [tag], group_guid: user.default_group_guid, domain: 'bit.ly' }),
  });
  assert.equal(response.status, 201);
  const link = await response.json();
  assert.ok(typeof link.id === 'string' && link.id.startsWith('bit.ly/'));
  saved = { id: link.id, group: user.default_group_guid, login: user.login };
  writeFileSync('bitlink.json', JSON.stringify(saved) + '\n', { mode: 0o600 });
}
const query = new URLSearchParams({ size: '100', archived: 'both', query: longUrl });
const page = await get(`/groups/${encodeURIComponent(saved.group)}/bitlinks?${query}`);
const retained = page.links.find((link) => link.id === saved.id);
assert.ok(retained, 'the authenticated group listing contains the created link');
assert.equal(retained.long_url, longUrl);
assert.equal(retained.title, title);
assert.deepEqual(retained.tags, [tag]);
assert.equal(retained.created_by, saved.login);
assert.equal(retained.archived, false);
assert.equal(retained.link, 'https://' + saved.id);
assert.equal(typeof page.pagination.search_after, 'string');
const tags = await get(`/groups/${encodeURIComponent(saved.group)}/tags`);
assert.ok(tags.tags.includes(tag));
console.log(JSON.stringify({ id: retained.id, destination: retained.long_url, group: saved.group, retained: process.argv[2] === 'readback' }));
